import{_ as r,o,c as e,a2 as a}from"./chunks/framework.D0_YsCyK.js";const p=JSON.parse('{"title":"搭建节点","description":"","frontmatter":{},"headers":[],"relativePath":"guide/nodes.md","filePath":"guide/nodes.md","lastUpdated":1792873292000}'),d={name:"guide/nodes.md"};function n(l,t,i,s,g,h){return o(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="搭建节点" tabindex="-1">搭建节点 <a class="header-anchor" href="#搭建节点" aria-label="Permalink to &quot;搭建节点&quot;">​</a></h1><p>在落地机上部署代理节点（入站）。所有配置由面板生成，节点上的 agent 只负责下载内核、写入配置、运行和守护进程。</p><blockquote><p>术语对照：面板菜单里的 <strong>落地</strong> 页就是本文档所说的节点 / 入站管理；菜单 <strong>规则</strong> 在文档里称转发（见 <a href="./forward">流量转发与管理</a>），菜单 <strong>共享</strong> 即联邦 / 面板共享（见 <a href="./relay">对接中转</a>）。</p></blockquote><h2 id="准备" tabindex="-1">准备 <a class="header-anchor" href="#准备" aria-label="Permalink to &quot;准备&quot;">​</a></h2><ul><li>落地机已按 <a href="./install">安装部署</a> 装好节点 agent，并在面板里显示在线</li><li>Linux amd64 / arm64，root 权限</li><li>建议安装 nftables（<code>apt install nftables</code>）：入站流量统计、白名单和 Hysteria2 端口跳跃依赖它；没有 nftables 时节点照常工作，只是没有这些功能</li></ul><h2 id="安装内核" tabindex="-1">安装内核 <a class="header-anchor" href="#安装内核" aria-label="Permalink to &quot;安装内核&quot;">​</a></h2><p><strong>落地</strong> 页 → <strong>内核</strong> 标签 → <strong>安装内核</strong> → 选择节点和内核。</p><table tabindex="0"><thead><tr><th>内核</th><th>版本</th><th>说明</th></tr></thead><tbody><tr><td>Xray</td><td>默认最新版，可指定</td><td>从 GitHub Release 下载，用官方校验文件校验</td></tr><tr><td>sing-box</td><td>默认最新版，可指定</td><td>从 GitHub Release 下载，用 Release 资产的 SHA256 校验</td></tr><tr><td>Snell</td><td>5.0.1 / 6.0.0 / 4.1.1</td><td>只从官方 <code>dl.nssurge.com</code> 下载，使用内置的校验值；6.0.0 为 beta、仅 v6 入站可用</td></tr></tbody></table><p>一台节点可以同时安装多个内核，内核按节点分组显示。点击内核可以启停、重启、查看日志、更换版本或卸载；节点重启后内核会自动恢复运行。</p><h2 id="新建入站" tabindex="-1">新建入站 <a class="header-anchor" href="#新建入站" aria-label="Permalink to &quot;新建入站&quot;">​</a></h2><p><strong>落地</strong> 页 → <strong>入站</strong> 标签 → <strong>新建入站</strong> → 选择节点和内核 → 点击一个快速模板 → 填名称 → <strong>创建并下发</strong>。</p><p>端口留空会随机分配，UUID、密码、密钥留空会自动生成。</p><table tabindex="0"><thead><tr><th>模板</th><th>内核</th><th>说明</th></tr></thead><tbody><tr><td>VLESS + Reality + Vision</td><td>Xray / sing-box</td><td>推荐，无需域名和证书</td></tr><tr><td>VLESS + XHTTP + Reality</td><td>Xray</td><td></td></tr><tr><td>Shadowsocks 2022</td><td>Xray / sing-box</td><td></td></tr><tr><td>Trojan + TLS（自签）</td><td>Xray / sing-box</td><td>需要填写域名</td></tr><tr><td>VMess + WS + TLS</td><td>Xray / sing-box</td><td>兼容老客户端</td></tr><tr><td>Hysteria2</td><td>sing-box</td><td>基于 QUIC，可选端口跳跃</td></tr><tr><td>TUIC v5</td><td>sing-box</td><td>基于 QUIC</td></tr><tr><td>AnyTLS</td><td>sing-box</td><td></td></tr><tr><td>SS2022 + ShadowTLS</td><td>sing-box</td><td>仅 TCP</td></tr><tr><td>NaïveProxy</td><td>sing-box</td><td>需要域名和真实证书</td></tr><tr><td>Snell / Snell + ShadowTLS</td><td>Snell</td><td>Surge 专用</td></tr></tbody></table><h3 id="证书" tabindex="-1">证书 <a class="header-anchor" href="#证书" aria-label="Permalink to &quot;证书&quot;">​</a></h3><p>TLS 类入站有三种证书来源：</p><ul><li><strong>自动生成自签证书</strong>：开箱即用，客户端需要允许不安全证书（分享链接已自动带上）</li><li><strong>使用节点上的证书文件</strong>：填写证书和私钥在节点上的绝对路径</li><li><strong>自动申请证书（ACME）</strong>：仅 sing-box，需要 sing-box 1.14 及以上 <ul><li>域名必须解析到该节点</li><li>HTTP 验证：节点 80 端口要能从公网访问</li><li>DNS 验证：支持 Cloudflare（API Token）和阿里云（AccessKey），不需要 80 端口</li><li>证书由 sing-box 自动续期</li></ul></li></ul><p>NaïveProxy 必须使用真实证书（ACME 或证书文件）。</p><h3 id="hysteria2-端口跳跃" tabindex="-1">Hysteria2 端口跳跃 <a class="header-anchor" href="#hysteria2-端口跳跃" aria-label="Permalink to &quot;Hysteria2 端口跳跃&quot;">​</a></h3><p>在 Hysteria2 入站里填写一段 UDP 端口，例如 <code>20000-30000</code>。节点会用 nftables 把这段端口转到入站端口，客户端在其中随机切换，缓解运营商对单个 UDP 端口的限速。</p><ul><li>范围不能包含入站端口本身，不能和其他入站、转发或节点的转发端口段重叠</li><li>只有直连地址带跳跃参数；经中转连接时只转发一个端口，不跳跃</li></ul><h3 id="监听地址" tabindex="-1">监听地址 <a class="header-anchor" href="#监听地址" aria-label="Permalink to &quot;监听地址&quot;">​</a></h3><p>默认监听 <code>::</code>（同时支持 IPv4 和 IPv6）。如果节点在内核启动参数里完全禁用了 IPv6（<code>ipv6.disable=1</code>），部分内核会绑定失败，此时在高级选项里把监听地址改为 <code>0.0.0.0</code>。</p><h3 id="空闲超时-秒" tabindex="-1">空闲超时（秒） <a class="header-anchor" href="#空闲超时-秒" aria-label="Permalink to &quot;空闲超时（秒）&quot;">​</a></h3><p>入站创建/编辑表单里的<strong>空闲超时（秒）</strong>：该入站的连接空闲超过设定秒数后由节点主动断开。留空表示不设置，走 Xray 默认 300 秒；填 <code>1–86400</code> 的整数；填 <code>0</code> 表示清除已设的值（与留空等效，恢复默认 300 秒；面板不下发显式的 0，Xray 层面 0 没有独立语义）。</p><ul><li><strong>仅 Xray 内核可用</strong>。sing-box 内核没有 Xray 式空闲超时（TCP 靠 keepalive 保活、UDP 会话默认 5 分钟清理、仅 TUN 有 <code>udp_timeout</code>），sing-box 入站上该字段禁用并会明示原因。</li><li>不同入站可设不同值，互不干扰；删除入站后对应的超时配置一并撤下。</li><li>已知行为（上游 Xray 侧，非面板缺陷）：VMess/SS 的完全静默会话在上游机制下约 1 秒即收尾，先于设定的定时器；批量传输后的会话关断约为设定值的 2 倍（如设 5 秒约 10 秒关断），会话均会被回收，只是时延为 2 倍。</li></ul><h3 id="出站" tabindex="-1">出站 <a class="header-anchor" href="#出站" aria-label="Permalink to &quot;出站&quot;">​</a></h3><p>服务器侧的分流和链式：客户端照常连本节点，由节点内核决定流量从哪里出去。想在客户端订阅里组合“中转 → 落地”，见 <a href="./subscription#链式代理">订阅的链式代理</a>。</p><p>点入站 → <strong>出站</strong>，有两部分（对话框顶部还能设置出站 IP 策略，见 <a href="#出站-ip-策略">出站 IP 策略</a>）：</p><ul><li><strong>默认去向</strong>：直连（从本节点出去），或选另一个入站（其他节点上的入站、导入的节点），流量再经它出去，网站看到的是它的 IP（链式代理）</li><li><strong>分流规则</strong>：按目标把一部分流量送到别处，从上到下匹配，先命中先生效，都不命中的走默认去向</li></ul><p>每条分流规则选分类或填自定义域名 / IP，再选去向：<strong>直连</strong>、<strong>阻断</strong> 或某个出站节点。</p><table tabindex="0"><thead><tr><th>分类</th><th>内容</th></tr></thead><tbody><tr><td>流媒体</td><td>Netflix、Disney+、YouTube、HBO、Prime Video、Spotify、TikTok</td></tr><tr><td>AI</td><td>ChatGPT、Claude、Gemini</td></tr><tr><td>常用</td><td>Google、Telegram</td></tr><tr><td>其他</td><td>广告、BT 下载、回国流量（中国大陆的域名和 IP）</td></tr></tbody></table><p>常见用法：</p><ul><li>只让 Netflix / ChatGPT 走有解锁 IP 的节点（例如导入的机场节点），其他流量照常直连</li><li>落地机阻断 BT 和回国流量，避免被投诉或滥用</li><li>A → B → C 多级：给 A 的入站选 B 作为默认去向，再给 B 的入站选 C；每个节点只连下一跳</li><li>自定义域名包含子域名，例如填 <code>example.com</code> 也匹配 <code>www.example.com</code></li></ul><p>注意事项：</p><ul><li>分类数据自动更新：Xray 用 v2fly 的 geosite / geoip 数据，节点每天检查一次，有新版本就下载、校验后替换并重启 Xray（启动失败会恢复原文件），内核日志里可以看到更新记录；sing-box 首次使用某个分类时下载规则集并缓存，之后每天更新。两者都经 <strong>网站配置</strong> 里的 GitHub 加速地址下载，落地机需要能访问</li><li>Xray 能连接 VLESS / VMess / Trojan / Shadowsocks（不含插件和 ShadowTLS）/ SOCKS5 / HTTP 出站节点；Hysteria2、TUIC、AnyTLS 等请用 sing-box 内核；Snell 内核的入站不能再设出站或分流</li><li>出站节点是本面板的自签证书入站时，Xray 用证书指纹校验；导入的节点如果跳过了证书验证，Xray 无法连接（新版 Xray 已移除 <code>allowInsecure</code>），请改用 sing-box</li><li>开启了“获取真实客户端 IP”的入站只能经中转连接，不能作为出站节点；只监听本机的入站只能被同一节点上的入站选用</li><li>出站节点开启了白名单时，会自动放行经它出站的节点；规则之间形成循环（A 经 B、B 又经 A）时无法保存</li><li>被选作默认去向或分流去向的入站不能直接删除，需先解除；订阅源刷新时也会保留这些节点。出站节点如果随<strong>节点一起被删除、或其所在内核被强制卸载</strong>，原本经它出去的流量会被丢弃（不会改为直连），请重新选择；被引用的入站所在内核<strong>普通卸载会被拒绝</strong>，需先解除引用或确认强制卸载。</li><li>用户流量统计照常按用户计算</li><li>保存会重启节点内核，正在经这个节点连接的会断开一下重连。如果你正用这个节点打开面板，保存时连接会中断，面板会在节点恢复后自动确认是否已保存</li><li>新配置让内核启动失败时（例如下载分流规则集失败），节点会自动恢复上一次能运行的配置并显示错误，不会因此掉线</li></ul><h2 id="分享与订阅" tabindex="-1">分享与订阅 <a class="header-anchor" href="#分享与订阅" aria-label="Permalink to &quot;分享与订阅&quot;">​</a></h2><ul><li>点击入站 → <strong>分享</strong>（电脑上也可以直接点行内的“分享”按钮）：显示通用分享链接和二维码；Snell 没有通用链接，显示 Surge 配置行。Surge 用户请使用 Surge 订阅</li><li><strong>订阅</strong> 页：一个链接包含落地和中转线路，可以建多个、分别过滤和改名，也可以分享给别人，见 <a href="./subscription">订阅</a></li><li><strong>分享地址</strong>：新建 / 编辑入站时可选客户端连接用的地址——<strong>自动</strong>（节点默认地址）、<strong>节点 IPv4</strong>、<strong>节点 IPv6</strong> 或 <strong>自定义域名 / IP</strong>。分享链接、订阅下发与链式代理的下一跳统一使用该地址；选 IPv4 / IPv6 后节点地址变化会自动跟随；节点没有对应地址族时不能选该档（保存会报错）。自定义地址须是规范主机名或 IP（尾点域名会自动规范化；含下划线、中文域名、回环地址的值不接受）</li></ul><table tabindex="0"><thead><tr><th>订阅格式</th><th>适用客户端</th><th>不包含</th></tr></thead><tbody><tr><td>自动识别</td><td>按客户端 UA 返回对应格式</td><td></td></tr><tr><td>Clash / Mihomo</td><td>Clash Verge、Stash、FlClash</td><td>NaïveProxy</td></tr><tr><td>sing-box</td><td>SFA / SFI / SFM</td><td>XHTTP</td></tr><tr><td>Shadowrocket</td><td>Shadowrocket</td><td>NaïveProxy</td></tr><tr><td>Loon</td><td>Loon</td><td>TUIC、gRPC、XHTTP、Snell、NaïveProxy</td></tr><tr><td>Quantumult X</td><td>Quantumult X</td><td>Hysteria2、TUIC、gRPC、XHTTP、ShadowTLS、Snell、NaïveProxy</td></tr><tr><td>通用 base64</td><td>v2rayN、NekoBox</td><td>Snell</td></tr><tr><td>Surge</td><td>Surge</td><td>VLESS、Reality、gRPC、XHTTP、NaïveProxy</td></tr></tbody></table><p>Snell 的下发按版本与客户端区分：Clash / Mihomo 与 Shadowrocket 下发 v4 / v5 入站（按 v4 客户端口径渲染），v6 入站不下发（客户端无 v6 支持）；sing-box 仅 1.14 及以上版本下发。注意：sing-box 是否下发 Snell 按<strong>拉取请求的 UA</strong> 判定（须 sing-box 1.14+ 的 UA），与是否用 <code>?format=</code> 指定格式无关；用浏览器或普通工具拉取（UA 不带 sing-box 版本）时不含 Snell，属正常现象，用 sing-box 1.14+ 客户端直接拉取（含 <code>?format=singbox</code> 链接）即可。另注意：导入的 Snell v1–v3 节点在 sing-box 订阅侧会被略过（sing-box 侧只下发 v4 / v6 口径），在其他格式中照常出现。</p><p>NaïveProxy 的 sing-box 出站需要 sing-box 1.13 及以上：节点 sing-box 低于 1.13 时，以 NaïveProxy 节点为链式落地（默认去向或分流目标）在保存、下发和更换内核版本时会被点名拒绝，把节点 sing-box 升到 1.13 及以上即可；订阅侧同理，sing-box 客户端低于 1.13（按拉取请求的 UA 判定）时不下发 NaïveProxy 节点、其余节点照常下发。自建 NaïveProxy 入站本身不受此下限影响。</p><blockquote><p>客户端版本提示：mihomo 1.19.15 及更早版本自身存在 Snell v4 支持缺陷，会整份拒绝含 Snell v4 节点的配置（mihomo 官方示例在该版本上同样失败），升级 mihomo 到较新版本（如 1.19.33）即可，与面板的渲染无关。</p></blockquote><p>VLESS 加密（ENC）入站不在上表的协议排除之列，但只有 Clash / Mihomo、Stash 与通用 base64 输出会携带它的完整 <code>encryption</code> 参数，其余格式（sing-box、Shadowrocket、Loon、Quantumult X、Surge）直接略过这类入站。</p><h2 id="批量操作" tabindex="-1">批量操作 <a class="header-anchor" href="#批量操作" aria-label="Permalink to &quot;批量操作&quot;">​</a></h2><p>入站多了不好管理时，点列表上方的 <strong>多选</strong>：点卡片勾选，<strong>全选</strong> 会选中当前列表里显示的全部入站（可以先用搜索或节点筛选缩小范围），然后可以批量 <strong>启用</strong>、<strong>停用</strong> 或 <strong>删除</strong>。每个受影响的内核只下发一次配置。</p><h2 id="节点延迟" tabindex="-1">节点延迟 <a class="header-anchor" href="#节点延迟" aria-label="Permalink to &quot;节点延迟&quot;">​</a></h2><p>面板可以让每个节点定时向一组测试点做 TCP 延迟探测，在节点卡片和列表里直接看到各线路的延迟。</p><h3 id="配置测试点" tabindex="-1">配置测试点 <a class="header-anchor" href="#配置测试点" aria-label="Permalink to &quot;配置测试点&quot;">​</a></h3><p><strong>网站配置 → 延迟测试</strong>：添加测试点（名称、地址、端口），最多 30 个；可以把最多 3 个固定显示在节点卡片上（其余的点进下拉查看）。仅管理员可配置。</p><p>测试点改名后，已选择该测试点的节点会自动跟随新名称；删除测试点后，相关节点回退到全局默认。</p><h3 id="查看延迟" tabindex="-1">查看延迟 <a class="header-anchor" href="#查看延迟" aria-label="Permalink to &quot;查看延迟&quot;">​</a></h3><p><strong>节点</strong> 页卡片视图和列表视图都有延迟显示：每个测试点一个数值，颜色按延迟分档：</p><table tabindex="0"><thead><tr><th>延迟</th><th>颜色</th></tr></thead><tbody><tr><td>&lt; 100ms</td><td>绿</td></tr><tr><td>100–300ms，或有丢包</td><td>橙</td></tr><tr><td>≥ 300ms，或丢包 ≥ 50%，或不可达</td><td>红</td></tr></tbody></table><h3 id="节点自选测试点" tabindex="-1">节点自选测试点 <a class="header-anchor" href="#节点自选测试点" aria-label="Permalink to &quot;节点自选测试点&quot;">​</a></h3><p>默认所有节点测全局启用的测试点。想让某个节点只测指定的点：节点操作菜单 → <strong>测试点</strong> → 切到自选并勾选，保存后会立即重测该节点。注意两种「空选」的区别：未启用自选时跟随全局默认；启用自选但不勾任何点，表示该节点<strong>不做</strong>延迟探测。</p><h2 id="本月流量-网卡" tabindex="-1">本月流量（网卡） <a class="header-anchor" href="#本月流量-网卡" aria-label="Permalink to &quot;本月流量（网卡）&quot;">​</a></h2><p><strong>节点</strong> 页卡片 / 列表与实时统计区显示每个节点的 <strong>本月流量（网卡）</strong>（上行 / 下行分列）：</p><ul><li>口径是<strong>整台机器网卡的流量</strong>（agent 上报网卡累计计数的差分），包含该机的一切流量，不只是经面板转发的业务；</li><li>按查看者浏览器时区的自然月统计（每月 1 日起算），逐小时落账；</li><li>这是机器用量的参考数字，与 <a href="./subscription#流量统计">订阅流量统计</a>（按订阅凭据计）和转发计费（按隧道倍率折算）的口径都不同，<strong>不能互相换算、不能作计费依据</strong>；</li><li>网卡增删不会重复计入；agent 或整机重启后的第一个统计窗口可能少计一小段，属已知口径。</li></ul><h2 id="节点调优" tabindex="-1">节点调优 <a class="header-anchor" href="#节点调优" aria-label="Permalink to &quot;节点调优&quot;">​</a></h2><p>一键优化节点内核的网络参数（sysctl），适合跨境、高延迟线路。</p><p>操作路径：<strong>节点</strong> 页 → 某节点的操作菜单 → <strong>调优</strong>（仅 agent 模式节点显示，nftables 模式节点没有此入口）。</p><table tabindex="0"><thead><tr><th>调优组</th><th>说明</th></tr></thead><tbody><tr><td>BBR 拥塞控制</td><td>高延迟、有丢包的线路提速明显（需要内核 4.9+）</td></tr><tr><td>加大缓冲区</td><td>跨境长距离线路单连接跑得更快</td></tr><tr><td>TCP 连接优化</td><td>开启 Fast Open、空闲后不降速、自动探测 MTU</td></tr><tr><td>高并发队列</td><td>连接多时不丢新连接</td></tr><tr><td>IPv4 转发</td><td>内核转发（nftables 端口转发）需要</td></tr><tr><td>文件句柄上限</td><td>系统允许打开更多连接和文件</td></tr></tbody></table><ul><li><strong>应用</strong>：勾选要启用的组 → 应用。参数写入 <code>/etc/sysctl.d/99-flmx-tuning.conf</code>，重启后依然生效；应用前各参数的原值会备份，<strong>恢复默认</strong> 时写回原值并删除该配置文件</li><li>不支持的内核参数只会 warning 跳过，不会中断整个应用过程</li><li>节点 agent 版本过旧时会提示升级节点后再试</li></ul><h2 id="回程路由追踪" tabindex="-1">回程路由追踪 <a class="header-anchor" href="#回程路由追踪" aria-label="Permalink to &quot;回程路由追踪&quot;">​</a></h2><p>查看节点到各测试点的回程经过了哪条骨干网，辅助判断线路质量。</p><p>操作路径：<strong>节点</strong> 页 → 点击延迟单元格，在下拉菜单里选 <strong>回程路由</strong> → 弹出路由详情，显示每一跳的 IP、延迟和所属线路。</p><p>自动识别的线路：</p><table tabindex="0"><thead><tr><th>线路</th><th>说明</th></tr></thead><tbody><tr><td>电信 CN2 GIA / CN2 GT</td><td>高端/普通 CN2</td></tr><tr><td>电信 163</td><td>普通电信</td></tr><tr><td>联通 4837 / 9929</td><td>普通/高端联通</td></tr><tr><td>移动 CMI / CMIN2</td><td>普通/高端移动</td></tr></tbody></table><p>路由结果每 24 小时自动刷新一次，失败时 6 小时后重试。需要节点有 raw socket 权限（root 或 <code>CAP_NET_RAW</code>），无权限时会优雅报错。</p><p>双栈节点会把每个测试点的 IPv4、IPv6 回程各测一条：路由详情里每个测试点分两行显示，节点卡片上 IPv6 线路与 IPv4 不同时多一个「v6」小标签，IPv6 线路变化也会在回程变化通知里单独一行提醒。双栈回程需要把节点 agent 升级到 1.2.0 或更高版本随附的版本；未升级的节点照常显示 IPv4 回程，不报错、不误报，升级后自动多出 IPv6 行。</p><h2 id="备份" tabindex="-1">备份 <a class="header-anchor" href="#备份" aria-label="Permalink to &quot;备份&quot;">​</a></h2><p>在 <strong>网站配置 → 数据备份与恢复</strong> 里勾选 <strong>内核与入站</strong>，会导出节点上的内核、所有入站（包括导入的节点）、中转线路和流量统计基准。所有订阅（包括分享出去的）也包含在内。恢复后面板会把内核配置重新推到在线的节点，离线的节点重连时自动补上。</p><p>恢复时的引用处置口径：导入的附属引用（限速绑定、入站的来源 / 出站 / 分流目标等）若指向不存在的行，会被剥离而不是整行丢弃，处置结果计入导入回执的 <code>ImportWarnings</code>；日报台账键（<code>notify_daily_last</code> 等运行状态）不随备份恢复，不会把当前值回滚成备份里的旧值；备份中的内核、中转（relay）或同名分组行被替换时，备份外指向旧行的引用会重指向恢复后的新行，同样计入 <code>ImportWarnings</code>，不会静默悬空。</p><p>注意：备份同样包含节点 SSH 配置与联邦（面板共享）的共享定义，敏感程度与面板数据库相当，备份文件请按凭据文件同等保管、不要随意外发。3.0.9 之前导出的备份不包含这部分，升级后请重新导出一次。（注：3.0.x 是本项目上游的旧版本线；现行 1.0.x 版本导出的备份均包含这部分，这句只针对从旧版本线带过来的存量备份。）</p><p>1.4.6 起可把同一份全量备份加密后上传到个人 GitHub 账号的私密 Gist、并定时自动上传（默认关闭、加密必填、最近 10 个版本可恢复）：见 <a href="./gist-backup">Gist 备份</a>。</p><p>下一步：<a href="./relay">对接中转</a></p><h2 id="pending-delete-管理接口-管理员" tabindex="-1">Pending Delete 管理接口（管理员） <a class="header-anchor" href="#pending-delete-管理接口-管理员" aria-label="Permalink to &quot;Pending Delete 管理接口（管理员）&quot;">​</a></h2><p>当节点离线时删除转发，系统会将其标记为 pending-delete（status=2），由后台任务按退避策略（1m/5m/30m/2h，上限 24h）自动重试清理。以下接口用于可观测性：</p><h3 id="post-api-v1-node-nftables-pending-deletes" tabindex="-1">POST /api/v1/node/nftables/pending-deletes <a class="header-anchor" href="#post-api-v1-node-nftables-pending-deletes" aria-label="Permalink to &quot;POST /api/v1/node/nftables/pending-deletes&quot;">​</a></h3><p>列出所有待清理的转发。</p><ul><li><strong>权限</strong>：仅管理员（roleID=0）</li><li><strong>请求</strong>：POST，无参数（需 Authorization 头带 JWT）</li><li><strong>响应</strong>：<code>{code, msg, data: [{forward_id, node_id, retry_count, next_retry_at, last_error}], ts}</code></li><li><strong>用途</strong>：退避耗尽转人工后，管理员在此查看哪些转发需要手动处理</li></ul><h3 id="相关行为" tabindex="-1">相关行为 <a class="header-anchor" href="#相关行为" aria-label="Permalink to &quot;相关行为&quot;">​</a></h3><ul><li>pending 行不会出现在转发列表中（<code>ListForwards</code> 恒过滤 status=2），只能通过上面的 pending-deletes 接口查看</li><li>配额释放、恢复、批量操作均不会复活 pending 行</li><li>隧道删除时，pending 行合并进同节点清理批次</li></ul><h2 id="删除节点" tabindex="-1">删除节点 <a class="header-anchor" href="#删除节点" aria-label="Permalink to &quot;删除节点&quot;">​</a></h2><p>在面板删除节点时，面板会先尝试通知节点清理它上面的转发服务和 nft 规则，然后再删除面板里的节点记录。但这个清理是<strong>尽力而为、不保证成功</strong>：</p><ul><li>节点在删除时离线或不可达，清理指令发不到节点，删除仍会继续（否则离线节点永远删不掉）</li><li>清理失败只会记进面板日志，不会阻止删除</li><li>删除节点时，如果其他节点上的入站正把本节点入站选作默认去向或分流去向，确认弹窗与删除响应会点名这些将被打断的跨节点引用（回传清单）；请先解除引用，或确认接受这些入站的出站流量被丢弃后再删除</li><li>节点机上的内核进程与配置文件不在面板的清理范围内</li></ul><p>所以：<strong>删除节点成功，不等于节点机上的运行时已经清干净。</strong> 推荐顺序：</p><ol><li>优先在节点还在线时删除，让面板的清理有机会执行</li><li>如果删除时节点已经离线，删除后登录节点机手动清理：停掉 agent / gost 服务，并清除该节点用过的 nft 规则</li></ol><h2 id="出站-ip-策略" tabindex="-1">出站 IP 策略 <a class="header-anchor" href="#出站-ip-策略" aria-label="Permalink to &quot;出站 IP 策略&quot;">​</a></h2><p>新建 / 编辑入站的<strong>高级选项</strong>，或入站的<strong>出站</strong>里，可设置“出站 IP 策略”：</p><ul><li><strong>自动（IPv4 / IPv6）</strong>：沿用内核和系统的默认选择。</li><li><strong>仅 IPv4 出站</strong>：保持入站监听地址不变，域名只解析 IPv4；直接请求 IPv6 目标会被拒绝，不会回退到 IPv6。这样客户端仍可通过 IPv6 连到节点，而本机的业务出站只走 IPv4。</li><li><strong>仅 IPv6 出站</strong>：保持入站监听地址不变，域名只解析 IPv6；直接请求 IPv4 目标会被拒绝，不会回退到 IPv4。节点必须具备可用的 IPv6 地址和路由，只支持 IPv4 的网站无法访问。</li><li><strong>优先 IPv4（失败回退 IPv6）</strong>：保留双栈解析，TCP 先尝试 IPv4；连接失败或约 250ms 内尚未连通时启动 IPv6 备用尝试，采用先成功的连接。域名没有 A 记录时直接尝试 IPv6。</li><li><strong>优先 IPv6（失败回退 IPv4）</strong>：与上面相反，TCP 先尝试 IPv6，失败或迟迟未连通时尝试 IPv4；域名没有 AAAA 记录时直接尝试 IPv4。</li></ul><p>优先模式需要 Xray 25.6.8+ 或 sing-box 1.12+；仅 IPv4 / 仅 IPv6 在 sing-box 上同样需要 1.12+。UDP 按解析结果优先选择地址；因为 UDP 没有连接握手，远端静默不回包无法可靠判定故障，不会自动把同一数据包重放到另一种 IP。</p><p>支持 Xray、sing-box 1.12 及以上（含 sing-box 内置 Snell），独立 Snell 内核不支持。策略按入站保存，编辑、重新下发和重启后仍生效；把节点内核降级到不支持已保存策略的版本会被拒绝。</p><p>指定出站 IP 策略时，高级 JSON 不能覆盖 <code>tag</code> 或 <code>detour</code>，以免绕过按入站生效的策略；存在冲突会提示并拒绝保存。</p><p>直连分流和用户流量统计同样遵循策略。链式 / 代理分流连接下一跳时也遵循所选 IP 策略：下一跳是与策略冲突的字面 IP 时保存会被拒绝（域名放行，由内核按同一策略解析）。网站最终看到的出口由下一跳节点决定，需要在最终落地上同样设置策略。</p>',94)])])}const c=r(d,[["render",n]]);export{p as __pageData,c as default};
